        ($$An `if` block that picks a message$$, FALSE, 0),
        ($$A `for` loop that builds a list$$, FALSE, 1),
        ($$A variable, such as `{name}`$$, TRUE, 2),
        ($$A calculation, such as `{a + b}`$$, TRUE, 3)
    ) AS v(option_text, is_correct, sort_order);

